const express = require('express');
const { RateLimiterRedis } = require('rate-limiter-flexible');
const Redis = require('ioredis');
const knex = require('knex')({ client: 'pg', connection: process.env.DATABASE_URL });

const app = express();
app.use(express.json());
const redisClient = new Redis(process.env.REDIS_URL);

const tierPoints = {
  ENTERPRISE: 1000,
  PRO: 200,
  FREE: 10
};

app.post('/api/ai/v1/completions', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Look up actual active subscription tier from database
  const subscription = await knex('user_subscriptions')
    .where({ user_id: req.user.id, status: 'ACTIVE' })
    .first();

  const actualTier = subscription ? subscription.tier : 'FREE';
  const pointsAllowed = tierPoints[actualTier] || 10;

  const limiter = new RateLimiterRedis({
    storeClient: redisClient,
    keyPrefix: `ai_limit_${actualTier}`,
    points: pointsAllowed,
    duration: 60
  });

  try {
    await limiter.consume(req.user.id, 1);
  } catch (err) {
    return res.status(429).json({ error: 'Rate limit exceeded for tier' });
  }

  res.json({ prompt: req.body.prompt, model: 'gpt-4o', generatedTokens: 150 });
});

app.listen(9005);
